        containmentAlwaysFalse: '\u0412\u044B\u0440\u0430\u0436\u0435\u043D\u0438\u0435 \u0432\u0441\u0435\u0433\u0434\u0430 \u0431\u0443\u0434\u0435\u0442 \u043E\u0446\u0435\u043D\u0438\u0432\u0430\u0442\u044C\u0441\u044F \u043A\u0430\u043A \u041B\u041E\u0416\u042C, \u0442\u0430\u043A \u043A\u0430\u043A \u0442\u0438\u043F\u044B "{leftType}" \u0438 "{rightType}" \u043D\u0435 \u043F\u0435\u0440\u0435\u043A\u0440\u044B\u0432\u0430\u044E\u0442\u0441\u044F',
